-- 17A P2 item (2) SQL part: private bucket 'agent-drafts' + admin-only SELECT for the unpublished cover (the object itself is moved by the Storage API: RUNBOOK-STORAGE-MOVES.md) [ROLLBACK]
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Restores the captured original policies/settings exactly (including the exposure they carried).
-- The bucket row 'agent-drafts' is left in place on purpose: no pack deletes any row or object.
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A / 13A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT');
  IF v IS DISTINCT FROM 'false' THEN f := f || ('bucket.agent-drafts.public: expected false but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT');
  IF v IS DISTINCT FROM '10485760' THEN f := f || ('bucket.agent-drafts.limit: expected 10485760 but live is ' || v); END IF;
  v := coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT');
  IF v IS DISTINCT FROM 'image/avif,image/gif,image/jpeg,image/png,image/svg+xml,image/webp' THEN f := f || ('bucket.agent-drafts.mime: expected image/avif,image/gif,image/jpeg,image/png,image/svg+xml,image/webp but live is ' || v); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'agent-drafts'), 'ABSENT');
  IF v IS DISTINCT FROM 'agent_drafts_admin_read' THEN f := f || ('sel.agent-drafts: expected agent_drafts_admin_read but live is ' || v); END IF;
  v := coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_drafts_admin_read'), 'ABSENT');
  IF v IS DISTINCT FROM 'SELECT|authenticated|PERMISSIVE' THEN f := f || ('pol.agent_drafts_admin_read.shape: expected SELECT|authenticated|PERMISSIVE but live is ' || v); END IF;
  v := coalesce((SELECT ((coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'agent-drafts' AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'is_admin')::text FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'agent_drafts_admin_read'), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('pol.agent_drafts_admin_read.tokens: expected true but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '17A ROLLBACK-P2: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

CREATE TEMP TABLE _kil17a_inv ON COMMIT DROP AS
SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('agent_drafts_admin_read')), '(null)')::text AS val
UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('agent-drafts')), '(null)')::text AS val;

-- bucket row intentionally LEFT IN PLACE (private, empty or not): deleting it would be a DELETE, and a bucket that already holds a moved draft must not be removed by a pack. Only the policy is dropped.
DROP POLICY agent_drafts_admin_read ON storage.objects;

DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'bucket.agent-drafts.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.agent-drafts.limit' AS name, coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.agent-drafts.mime' AS name, coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.agent-drafts' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'agent-drafts'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('bucket.agent-drafts.public', 'ABSENT OR false', ARRAY['ABSENT','false']::text[]),
  ('bucket.agent-drafts.limit', 'ABSENT OR 10485760', ARRAY['ABSENT','10485760']::text[]),
  ('bucket.agent-drafts.mime', 'ABSENT OR image/avif,image/gif,image/jpeg,image/png,image/svg+xml,image/webp', ARRAY['ABSENT','image/avif,image/gif,image/jpeg,image/png,image/svg+xml,image/webp']::text[]),
  ('sel.agent-drafts', '(none)', ARRAY['(none)']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A ROLLBACK-P2: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
END
$post$;
DO $invcheck$
DECLARE bad text;
BEGIN
  SELECT string_agg(a.name, ', ') INTO bad FROM _kil17a_inv a JOIN (
    SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('agent_drafts_admin_read')), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('agent-drafts')), '(null)')::text AS val
  ) b USING (name) WHERE a.val IS DISTINCT FROM b.val;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A ROLLBACK-P2: INVARIANT CHANGED (the pack must change nothing else; transaction rolls back): %', bad; END IF;
END
$invcheck$;

WITH a(name, actual) AS (
  SELECT 'bucket.agent-drafts.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.agent-drafts.limit' AS name, coalesce((SELECT coalesce(b.file_size_limit::text,'(null)') FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.agent-drafts.mime' AS name, coalesce((SELECT coalesce((SELECT string_agg(m, ',' ORDER BY m COLLATE "C") FROM unnest(b.allowed_mime_types) m),'(null)') FROM storage.buckets b WHERE b.id = 'agent-drafts'), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.agent-drafts' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'agent-drafts'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('bucket.agent-drafts.public', 'ABSENT OR false', ARRAY['ABSENT','false']::text[]),
  ('bucket.agent-drafts.limit', 'ABSENT OR 10485760', ARRAY['ABSENT','10485760']::text[]),
  ('bucket.agent-drafts.mime', 'ABSENT OR image/avif,image/gif,image/jpeg,image/png,image/svg+xml,image/webp', ARRAY['ABSENT','image/avif,image/gif,image/jpeg,image/png,image/svg+xml,image/webp']::text[]),
  ('sel.agent-drafts', '(none)', ARRAY['(none)']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'PRE' AS expected, 'PRE' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
COMMIT;
